mapper.select:
select o.*,rm.info_id,hif.img_url,hif.info_name from hotel_order as o inner join hotel_room as rm on FIND_IN_SET(rm.room_id,o.room_id) inner join hotel_info as hif on hif.info_id = rm.info_id where o.openid =#{parm.openid}
and o.status =#{parm.type}
GROUP BY o.order_id,o.room_id,o.room_code,o.status order by o.book_time desc
